import{obterJSON,endereco,consultaLimpa,variantesBusca,pontuarCorrespondencia}from'./comum.js';
const idiomasWiki=['pt','en','es','fr'];
async function consultar(projeto,idioma,termo,pagina,exato=false){const limite=30,offset=(pagina-1)*limite,base=`https://${idioma}.${projeto}.org`,u=new URL(base+'/w/api.php'),q=exato?`intitle:"${termo.replace(/"/g,' ')}"`:termo;Object.entries({action:'query',list:'search',srsearch:q,srnamespace:'0',srlimit:String(limite),sroffset:String(offset),srinfo:'totalhits',format:'json',origin:'*'}).forEach(([k,v])=>u.searchParams.set(k,v));const d=await obterJSON(u,12000,2),itens=d?.query?.search||[],total=Number(d?.query?.searchinfo?.totalhits)||itens.length;return{itens,total,temMais:offset+itens.length<total&&itens.length>0,base}}
function converter(projeto,idioma,base,p){const url=endereco(`${base}/wiki/${encodeURIComponent(String(p.title||'').replace(/ /g,'_'))}`);if(!url)return null;const nome=projeto==='wikibooks'?'Wikibooks':'Wikiversidade',tipo=projeto==='wikibooks'?'Livro didático / apostila aberta':'Material de estudo aberto';return{id:`${projeto}:${idioma}:${p.pageid}`,fonte:projeto,provedor:`${nome} ${idioma.toUpperCase()}`,titulo:p.title||'Sem título',autores:[],idiomas:[idioma],capa:null,descricao:String(p.snippet||'').replace(/<[^>]+>/g,' '),acessoLivre:true,dominioPublico:false,tipoAcesso:tipo,licenca:'Conteúdo educacional aberto de um projeto Wikimedia. A licença e a atribuição aplicáveis são indicadas na própria página.',origem:url,ler:url,texto:null,formatos:[]}}
async function pesquisar(projeto,q,o={}){const termo=consultaLimpa(q);if(!termo)return{livros:[],total:0,temMais:false};const pagina=Math.max(1,o.pagina||1),vars=variantesBusca(termo),mapa=new Map();let total=0,temMais=false,sucessos=0;const gerais=await Promise.allSettled(idiomasWiki.map(id=>consultar(projeto,id,vars[0],pagina,false)));for(let i=0;i<gerais.length;i++){const r=gerais[i];if(r.status!=='fulfilled')continue;sucessos++;total+=r.value.total;temMais||=r.value.temMais;for(const p of r.value.itens){const l=converter(projeto,idiomasWiki[i],r.value.base,p);if(l){l.relevancia=pontuarCorrespondencia(termo,l.titulo,[]);mapa.set(l.id,l)}}}if(pagina===1&&![...mapa.values()].some(l=>(l.relevancia||0)>=7000)){const exatas=await Promise.allSettled(idiomasWiki.map(id=>consultar(projeto,id,vars[0],1,true)));for(let i=0;i<exatas.length;i++){const r=exatas[i];if(r.status!=='fulfilled')continue;sucessos++;for(const p of r.value.itens){const l=converter(projeto,idiomasWiki[i],r.value.base,p);if(l){l.relevancia=pontuarCorrespondencia(termo,l.titulo,[]);mapa.set(l.id,l)}}}}if(!sucessos)throw new Error(`${projeto} indisponível`);const livros=[...mapa.values()].sort((a,b)=>(b.relevancia||0)-(a.relevancia||0));return{livros,total:total||livros.length,temMais}}
export const pesquisarWikibooks=(q,o)=>pesquisar('wikibooks',q,o);
export const pesquisarWikiversity=(q,o)=>pesquisar('wikiversity',q,o);
